#!/usr/bin/env node
/**
 * Export SEED_RULES from the data-platform seed module as SQL INSERTs.
 *
 * Single source of truth — run this script to regenerate the tax_rules
 * portion of infra/staging-data/seed.sql (or to emit SQL directly).
 *
 * Usage:
 *   node scripts/export-seed-sql.mjs                  # stdout
 *   node scripts/export-seed-sql.mjs --out <path>     # write to file
 *
 * Requires a build of @rajahinta/core-domain and @rajahinta/data-platform
 * (pnpm run build at workspace root).
 */

import { writeFileSync } from 'node:fs';
import { argv } from 'node:process';

// ---------------------------------------------------------------------------
// Formula reference constants — must match core-domain export values exactly.
// Kept as literals here so the export script works without importing from
// the TypeScript source tree (which would require tsx or a build step).
// ---------------------------------------------------------------------------
const FORMULA = {
  PER_LITRE_OF_PRODUCT: 'PER_LITRE_OF_PRODUCT',
  PER_LITRE_OF_ALCOHOL: 'PER_LITRE_OF_ALCOHOL',
  PER_CENTILITRE_ETHANOL: 'PER_CENTILITRE_ETHANOL',
  FLAT_PER_LITRE: 'FLAT_PER_LITRE',
};

const TAX_TYPES = {
  excise: 'excise',
  containerDuty: 'container_duty',
};

// ---------------------------------------------------------------------------
// Date helpers
// ---------------------------------------------------------------------------

function toPgTimestamp(d) {
  if (d === null || d === undefined) return 'NULL';
  return `'${d.toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, '+00:00')}'`;
}

function toPgJsonb(obj) {
  if (obj === null || obj === undefined) return 'NULL';
  const s = JSON.stringify(obj).replace(/'/g, "''");
  return `'${s}'::jsonb`;
}

function toPgString(s) {
  if (s === null || s === undefined) return 'NULL';
  return `'${s.replace(/'/g, "''")}'`;
}

function toPgNumeric(rateStr) {
  // Rate is stored as a string like "36.20" — emit as-is for numeric(12,6)
  return rateStr;
}

