// ---------------------------------------------------------------------------
// SQL generation
// ---------------------------------------------------------------------------

function emitSql(rules) {
  const lines = [];
  lines.push('-- ============================================================================');
  lines.push('-- Tax rules — auto-generated from SEED_RULES (single source of truth)');
  lines.push(`-- Generated: ${new Date().toISOString()}`);
  lines.push('-- Do NOT edit by hand — run: node scripts/export-seed-sql.mjs');
  lines.push('-- ============================================================================');
  lines.push('');

  lines.push('INSERT INTO tax_rules (tax_type, product_category, rate, effective_from, effective_to, exemption_conditions, calculation_formula_reference, official_source, verification_date, version_label)');
  lines.push('VALUES');

  const values = rules.map((r) => {
    const parts = [
      toPgString(r.taxType),
      toPgString(r.productCategory),
      toPgNumeric(r.rate),
      toPgTimestamp(r.effectiveFrom),
      toPgTimestamp(r.effectiveTo),
      toPgJsonb(r.exemptionConditions),
      toPgString(r.calculationFormulaReference),
      toPgString(r.officialSource),
      toPgTimestamp(r.verificationDate),
      toPgString(r.versionLabel),
    ];
    return `    (${parts.join(', ')})`;
  });

  lines.push(values.join(',\n'));
  lines.push(';');

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

const outIdx = argv.indexOf('--out');
const outPath = outIdx !== -1 ? argv[outIdx + 1] : null;
const sql = emitSql(SEED_RULES);

if (outPath) {
  writeFileSync(outPath, sql, 'utf8');
  process.stderr.write(`Wrote ${SEED_RULES.length} tax rules to ${outPath}\n`);
} else {
  process.stdout.write(sql + '\n');
}
